      "body": "本档是原型库里最年轻的一条，2026-10-29 首期即主导。它存在的理由很具体：过去七期，面板没有一个槽位能描述「股票在涨、债券在涨、而信用在恶化」这个组合。bond_vs_equity 管的是股债背离(债跌股涨)，本期不存在；stagflation_squeeze 管的是通胀高 + 增长弱，本期宏观核心还在，但它的价格层确认(股债同跌)已经撤回；inflation_reignite 与 growth_rolling 各只管一条腿。于是这个组合被拆散到几个档里去读，读到的东西就不完整。 本期的事实链条很短：分母端松了，分子端没松。分母端三个截面一致——10Y 月 -18bp(5.00%)、TIPS 月 **-19bp**(2.66%)、BEI 月只 +1bp(2.35%)，说明跌的是折现率而不是通胀预期；TLT 月 **+3.83%**、连续第三周收涨；10/27-28 的加息定价从 82.0% 砍到 **48.2%**，鹰鸽积分 7.0 → 1.2。分子端三个截面也一致——HY 月 +37bp(3.30%)、CCC 周 **+35bp**(13.45%、分位 100、半年 +435bp)；SOFR-IORB 由 -3bp 转 **+3bp**、净流动性月 **-89.7B**、LPI 从 5.1 跳到 **7.6**；核心 CPI 环比 +0.33% 连续第 3 月 >0.2%。 SPX 月线于是转正 (+0.51%)。但这个正号不可靠：距 60 日均值只剩 **16.97 点(0.22%)**，余量三期连降 140.7 → 26.45 → 16.97；广度 38.7/100，33 只样本只有 11 只站上 50 日均值、0 只创新高；NDX 月 -2.07%、SOX 月 -7.88%。也就是说指数在涨，内部在退，这与信用端的信号方向一致，与指数的方向相反。 AI 链本周给了一个很干净的例子：撤离路径第一次反向。最弱的存储/硬件端大幅反弹(SK 海力士周 +13.60%、三星 +7.61%、DELL +8.75%、MU +3.65%)，而现金流/模型层补跌(META 周 **-10.67%**、GOOGL 周 -5.79%、AMZN -3.63%)。这不是「全面转好」，是「超跌端反弹 + 强端补跌」——如果资金真的从避险转回风险偏好，模型层不该是跌得最狠的那一层。 还有一个反证必须并排：实际利率周 -14bp，黄金却跌 **2.40%**、白银跌 6.05%，同期 DXY 102.415(周 +0.62%、99 分位创新高)。上一期把「实际利率降、金价涨」写成经典传导重新接上，本周一周之内反向，该判断收回——现在驱动黄金的是美元。这条反证的意义是：分母端的松动可能只是「美元强、美债买盘回来」的机械结果，而不是「政策要转」的定价。 本档不做方向判断，只做三件事：记录背离、给出裁决点、标明哪一端更可能有前瞻性。历史上信用利差对违约的领先性通常早于股价 2-4 个季度，而本期走阔最猛的又是 CCC 这种真正会违约的一层，所以本档默认的怀疑方向是「股票这边定价得太早」。但怀疑不是结论——如果 HY 掉回 3.06 下方，那就是信用虚惊，本档该退役。",
      "core": "本档为 2026-10-29 新增，首期即 3/3 全命中并直接主导。它描述的是**同一份宏观数据被两条定价链读出了相反结论**：分母端(实际利率、政策路径)在松动，分子端(信用、融资条件、通胀)没松。股票把 10Y 月 -18bp、TIPS 月 -19bp、加息定价 82%→48.2% 读成「贴现率救赎」，于是 SPX 月线转正 +0.51%；信用把同一组数字读成「增长在坏、只是还没坏到报表上」，于是 HY 月 +37bp、CCC 周 +35bp。这两句话不可能同时对很久，本档的价值就是把这个矛盾显式化，并按 confirm / falsify 两端给出裁决点。",
