        "text": "credit_widen 锚维持 on，但内部结构本期出现第一次反转，这是上期判断需要修正的地方。HY OAS 3.30%(日 -8bp、周 **+1bp**、月 **+37bp**、98 分位)，30 日均值 3.058、当前高出 24bp；分档：IG 0.90%(月 +9bp)、BBB 1.12%(+13bp)、BB 1.98%(+22bp)、B 3.36%(+36bp)、CCC 13.45%(周 **+35bp**、月 **+217bp**、半年 **+435bp**、100 分位)。上一期我写过「B 级月 +63bp 已超过 HY 指数本身的 +61bp，走阔重心正从『只有 CCC』移到『B 及以下整段』」，并把它列为确认。本期这个梯度反了：B 级 +36bp **低于**指数 +37bp，BB 只有 +22bp，IG/BBB 只有 +9/+13bp。也就是说中段的走阔在减速，重心没有继续往上传导。但同一时间 CCC 周 +35bp 重新领跑——最弱端又加速了。合起来的图景是「压力停在 CCC/B 之间，反复而不扩散」，而不是上期说的「沿评级阶梯自下而上推进」。这个修正很重要，因为它决定性质：如果重心持续上移到 IG/BBB，那是系统性信用事件；如果停在 CCC，那更像「最弱一层在出清」，对指数的传染有限。偏「违约前瞻」的一侧：CCC 半年 +435bp、分位 100，B 级 3.36% 已在历史高位，这一层是真正会产生新增违约的；偏「贴现率重定价」的一侧：同期这段窗口里实际利率一度月 +19bp、MOVE 一度 101.70，HY 指数含相当比例长久期债，估值端本身会推高利差；而本期实际利率月 -19bp 回落，HY 却仍月 +37bp——这说明信用走阔里已经有一部分不是贴现率成分，这是新增的负面信息。观察：HY 能否站住 3.3、IG/BBB 是否被拖进来(一旦拖进来性质升级)、CCC 周线加速能否延续到月线、以及 HYG 与 TLT 的相对强弱(TLT 月 +3.83% 而 HY 利差走阔，两者正在背离)。",
